CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle and URL segment.
	"username" VARCHAR(30) NOT NULL UNIQUE,
	-- Login identity.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Free-text name shown on the profile.
	"display_name" VARCHAR(80) NOT NULL,
	-- Short profile blurb.
	"about" VARCHAR(160),
	-- Denormalised count of people following this account.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of pins saved by this account, across every board.
	"pin_count" INTEGER NOT NULL DEFAULT 0,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who saves things. Saving, not publishing, is the primary action here, which is why the interesting counters are about pins rather than posts.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."username" IS 'Public handle and URL segment.';
COMMENT ON COLUMN "users"."email" IS 'Login identity.';
COMMENT ON COLUMN "users"."display_name" IS 'Free-text name shown on the profile.';
COMMENT ON COLUMN "users"."about" IS 'Short profile blurb.';
COMMENT ON COLUMN "users"."follower_count" IS 'Denormalised count of people following this account.';
COMMENT ON COLUMN "users"."pin_count" IS 'Denormalised count of pins saved by this account, across every board.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "images" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- SHA-256 of the original bytes. The unique constraint is the whole point: the same picture saved a million times is one row, and the dedup happens at upload.
	"content_hash" CHAR(64) NOT NULL UNIQUE,
	-- Object-store key of the original. Renditions are addressed by convention from it.
	"storage_key" VARCHAR(400) NOT NULL,
	-- Pixel width, needed to lay out the masonry grid before the bytes arrive.
	"width" INTEGER NOT NULL,
	-- Pixel height. The aspect ratio is what determines a tile height in the grid, so both are required.
	"height" INTEGER NOT NULL,
	-- Hex placeholder colour painted while the image loads, which is why a grid never flashes white.
	"dominant_color" CHAR(7) NOT NULL DEFAULT '#eeeeee',
	-- Size of the original, for storage accounting.
	"byte_size" INTEGER NOT NULL,
	-- Account that first introduced the image. Null once that account is deleted; the image survives because others depend on it.
	"uploaded_by_id" BIGINT,
	-- First upload time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "images" IS 'The visual asset, stored once and shared by every pin of it. Separating the picture from the act of saving it is the decision the whole schema rests on.';
COMMENT ON COLUMN "images"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "images"."content_hash" IS 'SHA-256 of the original bytes. The unique constraint is the whole point: the same picture saved a million times is one row, and the dedup happens at upload.';
COMMENT ON COLUMN "images"."storage_key" IS 'Object-store key of the original. Renditions are addressed by convention from it.';
COMMENT ON COLUMN "images"."width" IS 'Pixel width, needed to lay out the masonry grid before the bytes arrive.';
COMMENT ON COLUMN "images"."height" IS 'Pixel height. The aspect ratio is what determines a tile height in the grid, so both are required.';
COMMENT ON COLUMN "images"."dominant_color" IS 'Hex placeholder colour painted while the image loads, which is why a grid never flashes white.';
COMMENT ON COLUMN "images"."byte_size" IS 'Size of the original, for storage accounting.';
COMMENT ON COLUMN "images"."uploaded_by_id" IS 'Account that first introduced the image. Null once that account is deleted; the image survives because others depend on it.';
COMMENT ON COLUMN "images"."created_at" IS 'First upload time.';

CREATE TABLE IF NOT EXISTS "boards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that created the board and controls its settings, even when others can add pins.
	"owner_id" BIGINT NOT NULL,
	-- Board title.
	"name" VARCHAR(100) NOT NULL,
	-- URL segment, unique within an owner rather than globally, so two people can both have a board called kitchens.
	"slug" VARCHAR(120) NOT NULL,
	-- Optional blurb on the board page.
	"description" VARCHAR(500),
	-- Secret boards are visible only to the owner and collaborators, and their pins are excluded from search and recommendation.
	"is_secret" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised pin total shown on every board tile.
	"pin_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of accounts following the board itself.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "boards" IS 'A named collection. Boards are the unit people follow and collaborate on, which is why they carry their own follower count and their own membership table.';
COMMENT ON COLUMN "boards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "boards"."owner_id" IS 'Account that created the board and controls its settings, even when others can add pins.';
COMMENT ON COLUMN "boards"."name" IS 'Board title.';
COMMENT ON COLUMN "boards"."slug" IS 'URL segment, unique within an owner rather than globally, so two people can both have a board called kitchens.';
COMMENT ON COLUMN "boards"."description" IS 'Optional blurb on the board page.';
COMMENT ON COLUMN "boards"."is_secret" IS 'Secret boards are visible only to the owner and collaborators, and their pins are excluded from search and recommendation.';
COMMENT ON COLUMN "boards"."pin_count" IS 'Denormalised pin total shown on every board tile.';
COMMENT ON COLUMN "boards"."follower_count" IS 'Denormalised count of accounts following the board itself.';
COMMENT ON COLUMN "boards"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_boards_owner_slug"
ON "boards" ("owner_id", "slug");

CREATE TABLE IF NOT EXISTS "board_sections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Board being subdivided.
	"board_id" BIGINT NOT NULL,
	-- Section title.
	"name" VARCHAR(100) NOT NULL,
	-- Manual order among the sections of a board.
	"position" SMALLINT NOT NULL DEFAULT 0,
	-- Denormalised pin total within the section.
	"pin_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "board_sections" IS 'One optional level of grouping inside a board. Deliberately not a tree: a fixed second level keeps every board query a two-table read instead of a recursive one.';
COMMENT ON COLUMN "board_sections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "board_sections"."board_id" IS 'Board being subdivided.';
COMMENT ON COLUMN "board_sections"."name" IS 'Section title.';
COMMENT ON COLUMN "board_sections"."position" IS 'Manual order among the sections of a board.';
COMMENT ON COLUMN "board_sections"."pin_count" IS 'Denormalised pin total within the section.';
COMMENT ON COLUMN "board_sections"."created_at" IS 'Creation time.';

CREATE INDEX "idx_board_sections_board_position"
ON "board_sections" ("board_id", "position");

CREATE TABLE IF NOT EXISTS "board_collaborators" (
	-- Board being shared.
	"board_id" BIGINT,
	-- Collaborator.
	"user_id" BIGINT,
	-- contributor | manager. Contributors add pins, managers can also invite and reorganise. The owner is not a row here - ownership stays on the board.
	"role" VARCHAR(12) NOT NULL DEFAULT 'contributor',
	-- pending | active. An invitation and a membership are the same row in two states.
	"status" VARCHAR(10) NOT NULL DEFAULT 'pending',
	-- Who sent the invitation. Null once that account is gone.
	"invited_by_id" BIGINT,
	-- When the invitation was accepted. Null while pending.
	"joined_at" TIMESTAMP,
	PRIMARY KEY("board_id", "user_id")
);

COMMENT ON TABLE "board_collaborators" IS 'Group boards. Because a pin records who saved it, a shared board stays attributable per pin rather than collapsing into one anonymous pile.';
COMMENT ON COLUMN "board_collaborators"."board_id" IS 'Board being shared.';
COMMENT ON COLUMN "board_collaborators"."user_id" IS 'Collaborator.';
COMMENT ON COLUMN "board_collaborators"."role" IS 'contributor | manager. Contributors add pins, managers can also invite and reorganise. The owner is not a row here - ownership stays on the board.';
COMMENT ON COLUMN "board_collaborators"."status" IS 'pending | active. An invitation and a membership are the same row in two states.';
COMMENT ON COLUMN "board_collaborators"."invited_by_id" IS 'Who sent the invitation. Null once that account is gone.';
COMMENT ON COLUMN "board_collaborators"."joined_at" IS 'When the invitation was accepted. Null while pending.';

CREATE INDEX "idx_board_collaborators_user_status"
ON "board_collaborators" ("user_id", "status");

CREATE TABLE IF NOT EXISTS "pins" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Visual being saved. Many pins point at one image, which is exactly what a repin is at the storage level.
	"image_id" BIGINT NOT NULL,
	-- Board the pin was saved to. A pin always lives on exactly one board; saving the same image twice makes two pins.
	"board_id" BIGINT NOT NULL,
	-- Section within the board. Null when the board has no sections or the pin is unfiled.
	"section_id" BIGINT,
	-- Account that performed this save. Not the original creator - on a repin the two differ, which is how attribution survives.
	"saver_id" BIGINT NOT NULL,
	-- Pin this was saved from. Null for an original upload, set for a repin. The direct parent, one hop up.
	"source_pin_id" BIGINT,
	-- First pin in the chain, copied down rather than walked. It is what makes "how far did this spread" a grouped count instead of a recursive query.
	"root_pin_id" BIGINT,
	-- Pin title, editable per save. Two people saving the same image can describe it differently, which is why this is on the pin and not the image.
	"title" VARCHAR(100),
	-- Pin note, also per save.
	"description" VARCHAR(800),
	-- Outbound link the pin points at. Carried down on a repin so the original source keeps its traffic.
	"destination_url" VARCHAR(2000),
	-- Denormalised count of pins whose source_pin_id is this one; the number shown as repins.
	"save_count" INTEGER NOT NULL DEFAULT 0,
	-- Save time. Board pages are ordered by this, newest first.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pins" IS 'A pin is a save, not an image. An original upload and a repin are the same row shape - the only difference is whether source_pin_id is set - so every feature built on pins works identically for both.';
COMMENT ON COLUMN "pins"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pins"."image_id" IS 'Visual being saved. Many pins point at one image, which is exactly what a repin is at the storage level.';
COMMENT ON COLUMN "pins"."board_id" IS 'Board the pin was saved to. A pin always lives on exactly one board; saving the same image twice makes two pins.';
COMMENT ON COLUMN "pins"."section_id" IS 'Section within the board. Null when the board has no sections or the pin is unfiled.';
COMMENT ON COLUMN "pins"."saver_id" IS 'Account that performed this save. Not the original creator - on a repin the two differ, which is how attribution survives.';
COMMENT ON COLUMN "pins"."source_pin_id" IS 'Pin this was saved from. Null for an original upload, set for a repin. The direct parent, one hop up.';
COMMENT ON COLUMN "pins"."root_pin_id" IS 'First pin in the chain, copied down rather than walked. It is what makes "how far did this spread" a grouped count instead of a recursive query.';
COMMENT ON COLUMN "pins"."title" IS 'Pin title, editable per save. Two people saving the same image can describe it differently, which is why this is on the pin and not the image.';
COMMENT ON COLUMN "pins"."description" IS 'Pin note, also per save.';
COMMENT ON COLUMN "pins"."destination_url" IS 'Outbound link the pin points at. Carried down on a repin so the original source keeps its traffic.';
COMMENT ON COLUMN "pins"."save_count" IS 'Denormalised count of pins whose source_pin_id is this one; the number shown as repins.';
COMMENT ON COLUMN "pins"."created_at" IS 'Save time. Board pages are ordered by this, newest first.';

CREATE INDEX "idx_pins_board_created"
ON "pins" ("board_id", "created_at");
CREATE INDEX "idx_pins_image_created"
ON "pins" ("image_id", "created_at");
CREATE INDEX "idx_pins_root"
ON "pins" ("root_pin_id");
CREATE INDEX "idx_pins_saver_created"
ON "pins" ("saver_id", "created_at");

CREATE TABLE IF NOT EXISTS "pin_reactions" (
	-- Pin reacted to.
	"pin_id" BIGINT,
	-- Account reacting. The pair is the key, so switching reaction is an UPDATE.
	"user_id" BIGINT,
	-- good_idea | love | thanks | wow | haha. Reactions here are feedback on the save, not a substitute for saving - saving is the real signal.
	"reaction" VARCHAR(12) NOT NULL,
	-- When the reaction was first given.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("pin_id", "user_id")
);

COMMENT ON TABLE "pin_reactions" IS 'Lightweight feedback. It sits on the pin rather than the image so a reaction attaches to one save with its own title and note, not to every copy of the picture.';
COMMENT ON COLUMN "pin_reactions"."pin_id" IS 'Pin reacted to.';
COMMENT ON COLUMN "pin_reactions"."user_id" IS 'Account reacting. The pair is the key, so switching reaction is an UPDATE.';
COMMENT ON COLUMN "pin_reactions"."reaction" IS 'good_idea | love | thanks | wow | haha. Reactions here are feedback on the save, not a substitute for saving - saving is the real signal.';
COMMENT ON COLUMN "pin_reactions"."created_at" IS 'When the reaction was first given.';

CREATE TABLE IF NOT EXISTS "pin_comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Pin being commented on.
	"pin_id" BIGINT NOT NULL,
	-- Commenter.
	"author_id" BIGINT NOT NULL,
	-- Comment being replied to. Null for a top-level comment.
	"parent_comment_id" BIGINT,
	-- Comment text.
	"body" VARCHAR(500) NOT NULL,
	-- Posting time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pin_comments" IS 'Discussion on a specific save. Comments do not follow a repin, which is deliberate: the new pin is a different save with a different audience.';
COMMENT ON COLUMN "pin_comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pin_comments"."pin_id" IS 'Pin being commented on.';
COMMENT ON COLUMN "pin_comments"."author_id" IS 'Commenter.';
COMMENT ON COLUMN "pin_comments"."parent_comment_id" IS 'Comment being replied to. Null for a top-level comment.';
COMMENT ON COLUMN "pin_comments"."body" IS 'Comment text.';
COMMENT ON COLUMN "pin_comments"."created_at" IS 'Posting time.';

CREATE INDEX "idx_pin_comments_pin_created"
ON "pin_comments" ("pin_id", "created_at");

CREATE TABLE IF NOT EXISTS "user_follows" (
	-- Account doing the following.
	"follower_id" BIGINT,
	-- Account followed - which here means every board they own, now and in future.
	"followee_id" BIGINT,
	-- When the follow started.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("follower_id", "followee_id")
);

COMMENT ON TABLE "user_follows" IS 'Following a person subscribes you to their whole taste. Kept apart from board follows because the two resolve to different sets of pins and are unsubscribed independently.';
COMMENT ON COLUMN "user_follows"."follower_id" IS 'Account doing the following.';
COMMENT ON COLUMN "user_follows"."followee_id" IS 'Account followed - which here means every board they own, now and in future.';
COMMENT ON COLUMN "user_follows"."created_at" IS 'When the follow started.';

CREATE INDEX "idx_user_follows_followee_created"
ON "user_follows" ("followee_id", "created_at");

CREATE TABLE IF NOT EXISTS "board_follows" (
	-- Board followed.
	"board_id" BIGINT,
	-- Follower.
	"user_id" BIGINT,
	-- When the follow started.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("board_id", "user_id")
);

COMMENT ON TABLE "board_follows" IS 'Following one board without following its owner. Two follow tables rather than one polymorphic edge: each carries a real foreign key, and the home feed is a union of two indexed reads.';
COMMENT ON COLUMN "board_follows"."board_id" IS 'Board followed.';
COMMENT ON COLUMN "board_follows"."user_id" IS 'Follower.';
COMMENT ON COLUMN "board_follows"."created_at" IS 'When the follow started.';

CREATE INDEX "idx_board_follows_user_created"
ON "board_follows" ("user_id", "created_at");

CREATE TABLE IF NOT EXISTS "saved_searches" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that saved the search.
	"user_id" BIGINT NOT NULL,
	-- Search text exactly as typed, so it can be re-run and shown back verbatim.
	"query" VARCHAR(200) NOT NULL,
	-- Facets applied alongside the text, e.g. colour or aspect ratio. JSON because the facet set changes with the product and none of it is ever joined on.
	"filters" JSONB,
	-- Sends a digest when new pins match. This is what turns a saved search from a shortcut into a subscription.
	"notify_on_new" BOOLEAN NOT NULL DEFAULT false,
	-- Last time the digest job evaluated it. Null until the first run, and the watermark new matches are measured against.
	"last_run_at" TIMESTAMP,
	-- When it was saved.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "saved_searches" IS 'A stored query, not stored results. Re-running it is cheap and always current, whereas a materialised result set would be stale the moment anyone pinned anything.';
COMMENT ON COLUMN "saved_searches"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "saved_searches"."user_id" IS 'Account that saved the search.';
COMMENT ON COLUMN "saved_searches"."query" IS 'Search text exactly as typed, so it can be re-run and shown back verbatim.';
COMMENT ON COLUMN "saved_searches"."filters" IS 'Facets applied alongside the text, e.g. colour or aspect ratio. JSON because the facet set changes with the product and none of it is ever joined on.';
COMMENT ON COLUMN "saved_searches"."notify_on_new" IS 'Sends a digest when new pins match. This is what turns a saved search from a shortcut into a subscription.';
COMMENT ON COLUMN "saved_searches"."last_run_at" IS 'Last time the digest job evaluated it. Null until the first run, and the watermark new matches are measured against.';
COMMENT ON COLUMN "saved_searches"."created_at" IS 'When it was saved.';

CREATE UNIQUE INDEX "uq_saved_searches_user_query"
ON "saved_searches" ("user_id", "query");

